@Unique('users_email_key', ['email'])
@Check(
  'password_null_when_not_present',
  "(((password IS NOT NULL) AND ('password'::login_method_enum = ANY (login_methods))) OR ((password IS NULL) AND (NOT ('password'::login_method_enum = ANY (login_methods)))))",
)
@Index('users_role_id_idx', ['role_id'])
@Entity({ name: 'users', schema: 'public' })
export class Users {
  @PrimaryColumn({
    name: 'id',
    type: 'varchar',
    length: 255,
    primaryKeyConstraintName: 'users_pkey',
  })
  id!: string;

  @Column({ name: 'email', type: 'varchar', length: 255 })
  email!: string;

  @Column({ name: 'password', type: 'varchar', length: 255, nullable: true })
  password!: string | null;

  @Column({ name: 'first_name', type: 'varchar', length: 255 })
  first_name!: string;

  @Column({ name: 'last_name', type: 'varchar', length: 255 })
  last_name!: string;

  @Column({ name: 'role', type: 'varchar', length: 255, nullable: true })
  role!: string | null;

  @Column({
    name: 'approved_by_admin',
    type: 'bool',
    nullable: true,
    default: false,
  })
  approved_by_admin!: boolean | null;

  @Column({
    name: 'rejected_by_admin',
    type: 'bool',
    nullable: true,
    default: false,
  })
  rejected_by_admin!: boolean | null;

  @Column({ name: 'created_at', type: 'timestamptz' })
  created_at!: Date;

  @Column({ name: 'updated_at', type: 'timestamptz' })
  updated_at!: Date;

  @Column({ name: 'org_id', type: 'varchar', length: 255 })
  org_id!: string;

  @Column({
    name: 'login_methods',
    type: 'enum',
    enum: ['password', 'saml'],
    enumName: 'login_method_enum',
    array: true,
    default: () => "ARRAY['password'::login_method_enum]",
  })
  login_methods!: LoginMethodEnum[];

  @Column({ name: 'role_id', type: 'uuid' })
  role_id!: string;

  @ManyToOne('Orgs', {
    onDelete: 'CASCADE',
    onUpdate: 'NO ACTION',
    nullable: false,
  })
  @JoinColumn({
    name: 'org_id',
    referencedColumnName: 'id',
    foreignKeyConstraintName: 'users_org_id_fkey',
  })
  org?: Relation<Orgs>;

  @ManyToOne('Roles', {
    onDelete: 'RESTRICT',
    onUpdate: 'NO ACTION',
    nullable: false,
  })
  @JoinColumn({
    name: 'role_id',
    referencedColumnName: 'id',
    foreignKeyConstraintName: 'users_role_id_fkey',
  })
  role_id_rel?: Relation<Roles>;
}

